下面是一个用 Python 实现的最小堆（Min Heap）示例，支持 `insert` 和 `extract_min` 操作，并附带一些常用辅助方法：

```python
class MinHeap:
    def __init__(self):
        self.heap = []

    def _parent(self, i):
        return (i - 1) // 2

    def _left_child(self, i):
        return 2 * i + 1

    def _right_child(self, i):
        return 2 * i + 2

    def _swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

    def _sift_up(self, i):
        # 向上调整，维护最小堆性质
        while i > 0:
            p = self._parent(i)
            if self.heap[i] < self.heap[p]:
                self._swap(i, p)
                i = p
            else:
                break

    def _sift_down(self, i):
        # 向下调整，维护最小堆性质
        n = len(self.heap)
        while True:
            left = self._left_child(i)
            right = self._right_child(i)
            smallest = i

            if left < n and self.heap[left] < self.heap[smallest]:
                smallest = left
            if right < n and self.heap[right] < self.heap[smallest]:
                smallest = right

            if smallest != i:
                self._swap(i, smallest)
                i = smallest
            else:
                break

    def insert(self, value):
        # 插入新元素并向上调整
        self.heap.append(value)
        self._sift_up(len(self.heap) - 1)

    def extract_min(self):
        # 取出并删除最小元素（堆顶），然后向下调整
        if not self.heap:
            raise IndexError("extract_min from empty heap")
        if len(self.heap) == 1:
            return self.heap.pop()

        min_val = self.heap[0]
        # 将最后一个元素移到堆顶
        self.heap[0] = self.heap.pop()
        self._sift_down(0)
        return min_val

    def peek_min(self):
        if not self.heap:
            raise IndexError("peek_min from empty heap")
        return self.heap[0]

    def is_empty(self):
        return len(self.heap) == 0

    def size(self):
        return len(self.heap)

    def __len__(self):
        return len(self.heap)


# 简单测试
if __name__ == "__main__":
    h = MinHeap()
    for x in [5, 3, 8, 1, 2]:
        h.insert(x)
        print("插入后堆:", h.heap)

    print("最小元素:", h.peek_min())
    while not h.is_empty():
        print("取出最小:", h.extract_min())
        print("当前堆:", h.heap)
```

说明要点：
- 使用数组 `self.heap` 存储堆元素。
- `insert`：将新元素追加到末尾，然后 `_sift_up` 向上调整。
- `extract_min`：取出堆顶，将最后一个元素移到堆顶，然后 `_sift_down` 向下调整。
- 时间复杂度：
  - `insert`：O(log n)
  - `extract_min`：O(log n)
  - `peek_min`：O(1)

